+
+// Segments combines multiple segment keys using a logical operator.
+type Segments struct {
+	Keys            []string `yaml:"keys"`
+	SegmentOperator string   `yaml:"operator"`
+}
+
+func (Segments) isSegment() {}
+
+// SegmentEmbed preserves the YAML representation of a rule segment.
+type SegmentEmbed struct{ Segment IsSegment }
+
+func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
+	if s == nil {
+		return nil, fmt.Errorf("missing segment")
+	}
+	switch v := s.Segment.(type) {
+	case SegmentKey:
+		if v == "" {
+			return nil, fmt.Errorf("empty segment key")
+		}
+		return string(v), nil
+	case Segments:
+		if err := validateSegments(v); err != nil {
+			return nil, err
+		}
+		return v, nil
+	default:
+		return nil, fmt.Errorf("invalid segment type %T", s.Segment)
+	}
+}
+
+func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
+	var raw interface{}
+	if err := unmarshal(&raw); err != nil {
+		return err
+	}
+	switch v := raw.(type) {
+	case string:
+		if v == "" {
+			return fmt.Errorf("empty segment key")
+		}
+		s.Segment = SegmentKey(v)
+		return nil
+	case map[interface{}]interface{}:
+		if len(v) != 2 {
+			return fmt.Errorf("segment object requires keys and operator")
+		}
+		keysRaw, keysOK := v["keys"]
+		opRaw, opOK := v["operator"]
+		if !keysOK || !opOK {
+			return fmt.Errorf("segment object requires keys and operator")
+		}
+		list, ok := keysRaw.([]interface{})
+		if !ok {
+			return fmt.Errorf("segment keys must be a list")
+		}
+		keys := make([]string, 0, len(list))
+		for _, item := range list {
+			key, ok := item.(string)
+			if !ok || key == "" {
+				return fmt.Errorf("segment keys must be nonempty strings")
+			}
+			keys = append(keys, key)
+		}
+		op, ok := opRaw.(string)
+		if !ok {
+			return fmt.Errorf("segment operator must be a string")
+		}
+		segments := Segments{Keys: keys, SegmentOperator: op}
+		if err := validateSegments(segments); err != nil {
+			return err
+		}
+		s.Segment = segments
+		return nil
+	default:
+		return fmt.Errorf("segment must be a string or keys/operator object")
+	}
+}
+
+func validateSegments(s Segments) error {
+	if len(s.Keys) == 0 {
+		return fmt.Errorf("segment keys must not be empty")
+	}
+	for _, key := range s.Keys {
+		if key == "" {
+			return fmt.Errorf("segment keys must be nonempty strings")
+		}
+	}
+	if len(s.Keys) > 1 && s.SegmentOperator != "AND_SEGMENT_OPERATOR" && s.SegmentOperator != "OR_SEGMENT_OPERATOR" {
+		return fmt.Errorf("invalid segment operator %q", s.SegmentOperator)
+	}
+	return nil
+}
+
+// KeysOperator returns the RPC-ready segment keys and operator.
+func (s SegmentEmbed) KeysOperator() ([]string, string, error) {
+	switch v := s.Segment.(type) {
+	case SegmentKey:
+		if v == "" {
+			return nil, "", fmt.Errorf("missing segment")
+		}
+		return []string{string(v)}, "OR_SEGMENT_OPERATOR", nil
+	case Segments:
+		if err := validateSegments(v); err != nil {
+			return nil, "", err
+		}
+		if len(v.Keys) == 1 {
+			return v.Keys, "OR_SEGMENT_OPERATOR", nil
+		}
+		return v.Keys, v.SegmentOperator, nil
+	default:
+		return nil, "", fmt.Errorf("missing or invalid segment")
+	}
+}
